class KeyTally {
  private c = new Map<string, number>();

  inc(key: string): void {
    this.c.set(key, (this.c.get(key) ?? 0) + 1);
  }

  dec(key: string): void {
    const v = this.c.get(key)! - 1;
    if (v === 0) this.c.delete(key);
    else this.c.set(key, v);
  }

  getMaxKey(): string {
    let best = "", bc = -1;
    for (const [k, v] of this.c) if (v > bc) { bc = v; best = k; }
    return best;
  }

  getMinKey(): string {
    let best = "", bc = Infinity;
    for (const [k, v] of this.c) if (v < bc) { bc = v; best = k; }
    return best;
  }
}

