class Bucket {
  keys = new Set<string>();
  prev: Bucket | null = null;
  next: Bucket | null = null;
  constructor(public count: number) {}
}

class KeyTally {
  private head = new Bucket(0);        // before the smallest count
  private tail = new Bucket(Infinity); // after the largest count
  private where = new Map<string, Bucket>();

  constructor() {
    this.head.next = this.tail;
    this.tail.prev = this.head;
  }

  private insertAfter(b: Bucket, count: number): Bucket {
    const nb = new Bucket(count);
    nb.prev = b;
    nb.next = b.next;
    b.next!.prev = nb;
    b.next = nb;
    return nb;
  }

  private removeKey(b: Bucket, key: string): void {
    b.keys.delete(key);
    if (b.keys.size === 0) {
      b.prev!.next = b.next;
      b.next!.prev = b.prev;
    }
  }

  inc(key: string): void {
    const cur = this.where.get(key) ?? this.head;
    let nxt = cur.next!;
    if (nxt.count !== cur.count + 1) nxt = this.insertAfter(cur, cur.count + 1);
    nxt.keys.add(key);
    this.where.set(key, nxt);
    if (cur !== this.head) this.removeKey(cur, key);
  }

  dec(key: string): void {
    const cur = this.where.get(key)!;
    if (cur.count === 1) {
      this.where.delete(key);
    } else {
      let prv = cur.prev!;
      if (prv.count !== cur.count - 1) prv = this.insertAfter(prv, cur.count - 1);
      prv.keys.add(key);
      this.where.set(key, prv);
    }
    this.removeKey(cur, key);
  }

  getMaxKey(): string {
    return this.tail.prev === this.head ? "" : this.tail.prev!.keys.values().next().value!;
  }

  getMinKey(): string {
    return this.head.next === this.tail ? "" : this.head.next!.keys.values().next().value!;
  }
}

