        self.head, self.tail = Bucket(0), Bucket(float("inf"))
        self.head.next, self.tail.prev = self.tail, self.head
        self.where = {}

    def _insert_after(self, b, count):
        nb = Bucket(count)
        nb.prev, nb.next = b, b.next
        b.next.prev = nb
        b.next = nb
        return nb

    def _remove_key(self, b, key):
        b.keys.discard(key)
        if not b.keys:
            b.prev.next, b.next.prev = b.next, b.prev

    def inc(self, key: str) -> None:
        cur = self.where.get(key, self.head)
        nxt = cur.next
        if nxt.count != cur.count + 1:
            nxt = self._insert_after(cur, cur.count + 1)
        nxt.keys.add(key)
        self.where[key] = nxt
        if cur is not self.head:
            self._remove_key(cur, key)

    def dec(self, key: str) -> None:
        cur = self.where[key]
        if cur.count == 1:
            del self.where[key]
        else:
            prv = cur.prev
            if prv.count != cur.count - 1:
                prv = self._insert_after(prv, cur.count - 1)
            prv.keys.add(key)
            self.where[key] = prv
        self._remove_key(cur, key)

    def getMaxKey(self) -> str:
        return "" if self.tail.prev is self.head else next(iter(self.tail.prev.keys))

    def getMinKey(self) -> str:
        return "" if self.head.next is self.tail else next(iter(self.head.next.keys))

